import re
with open('/workdir/data/access.log') as f:
    lines = f.readlines()
log_pattern = re.compile(r'^(\S+)\s+\S+\s+\S+\s+\[.*?\]\s+\"([A-Z]+)\s+(.*)\s+HTTP/\S+\"\s+(\d+)\s+(\d+)\s+\".*?\"\s+\".*?\"$')
for line in lines:
    line = line.strip()
    if not line:
        continue
    m = log_pattern.match(line)
    if m:
        print(f'IP: {m.group(1)}, method: {m.group(2)}, path: {m.group(3)}, status: {m.group(4)}, size: {m.group(5)}')
""}
